public class TextNodeTest {
    private static final String WHITESPACE = "   ";
    private static final String BLANK = "";
    private static final String EMPTY_STRING = "";

    @Test
    public void getNodeNameTest() {
        TextNode node = new TextNode(WHITESPACE);
        Assert.assertEquals("text", node.nodeName());
    }

    @Test
    public void getTextTest() {
        TextNode node = new TextNode(WHITESPACE);
        Assert.assertEquals(WHITESPACE, node.text());
    }

    @Test
    public void getTextAfterConstructionTest() {
        TextNode node = new TextNode();
        Assert.assertNull(node.text());
    }

    @Test
    public void textMethodUpdatesTextNodeContentTest() {
        TextNode node = new TextNode(EMPTY_STRING);
        node.text(WHITESPACE);
        Assert.assertEquals(WHITESPACE, node.text());
    }

    @Test
    public void getWholeTextTest() {
        TextNode node = new TextNode(WHITESPACE);
        Assert.assertEquals(WHITESPACE, node.getWholeText());
    }

    @Test
    public void isBlankTest() {
        TextNode node = new TextNode(WHITESPACE);
        Assert.assertTrue(node.isBlank());

        TextNode node2 = new TextNode(BLANK);
        Assert.assertFalse(node2.isBlank());
    }

    @Test
    public void splitTextZeroOffsetReturnsSameTextNodeTest() throws IOException {
        TextNode node = new TextNode(WHITESPACE);
        TextNode newNode = node.splitText(0);
        Assert.assertEquals(node, newNode);
    }

    @Test
    public void splitTextNonZeroOffsetChangesTextNodeContentTest() throws IOException {
        TextNode node = new TextNode("a");
        TextNode newNode = node.splitText(1);
        Assert.assertEquals("a", newNode.text());
    }

    @Test
    public void outerHtmlHeadTest() throws IOException {
        // Mock Appendable and Document.OutputSettings to avoid actual implementation
        Appendable accum = mock(Appendable.class);
        Document.OutputSettings out = mock(Document.OutputSettings.class);

        TextNode node = new TextNode(WHITESPACE);
        new TextNode().outerHtmlHead(accum, 0, out);

        verify(accum).append(String.valueOf("\n" + WHITESPACE));
    }

    @Test
    public void outerHtmlTailTest() {
        // Mock Appendable to avoid actual implementation
        Appendable accum = mock(Appendable.class);

        TextNode node = new TextNode(WHITESPACE);
        new TextNode().outerHtmlTail(accum, 0);

        verify(accum).append(String.valueOf("\n"));
    }

    @Test
    public void cloneTest() {
        // Mock Document to avoid actual implementation
