        TextNode node = new TextNode(WHITESPACE);
        TextNode clonedNode = node.clone();

        Assert.assertSame(node, clonedNode);
    }

    @Test
    public void createFromEncodedTest() {
        String encodedText = "a";
        TextNode node = TextNode.createFromEncoded(encodedText);

        Assert.assertEquals(encodedText, node.text());
    }

    @Test
    public void normaliseWhitespaceTest() {
        Assert.assertEquals("   ", TextNode.normaliseWhitespace(WHITESPACE));
    }

    @Test
    public void stripLeadingWhitespaceTest() {
        Assert.assertEquals("", TextNode.stripLeadingWhitespace(BLANK));
    }

